// Veridact capture agent.
//
// The camera is opened here and the frame is hashed + signed straight out of
// memory. There is deliberately NO file input in this flow: if the user could
// choose the bytes, they could choose AI-generated bytes, and the signature
// would prove nothing about capture (decisions/0003).
//
// decisions/0008: the device's key is no longer pasted in by hand. It's
// fetched from this browser's own IndexedDB keystore (keystore.js) — for
// ECDSA P-256, that's a non-extractable CryptoKey that can sign but was
// never readable as text in the first place. Enrolling (or importing a
// legacy key once) is the only time key material is handled at all.

const $ = (id) => document.getElementById(id);
let stream = null;
let lastManifest = null;
let lastBlob = null;
let devices = [];

function showErr(m) { $("err").textContent = m; $("err").classList.remove("hidden"); }

(async function populateDevices() {
  devices = await vdListDevices();
  if (!devices.length) {
    $("no-devices").classList.remove("hidden");
    $("capture-card").classList.add("hidden");
    return;
  }
  const sel = $("handle");
  sel.innerHTML = devices.map(d =>
    `<option value="${d.handle}">${d.handle} (${d.algorithm})</option>`
  ).join("");
  const last = vdGetLastHandle();
  if (last && devices.some(d => d.handle === last)) sel.value = last;
  sel.addEventListener("change", () => vdSetLastHandle(sel.value));
})();

$("start").addEventListener("click", async () => {
  $("err").classList.add("hidden");
  try {
    stream = await navigator.mediaDevices.getUserMedia({
      video: { width: { ideal: 1280 }, height: { ideal: 720 } },
      audio: false,
    });
  } catch (e) {
    return showErr("Could not open the camera: " + e.message +
      ". Veridact can only attest live captures, so a camera is required.");
  }
  const v = $("preview");
  v.srcObject = stream;
  await v.play();
  $("camstate").textContent = `Live — ${v.videoWidth}x${v.videoHeight}`;
  $("viewfinder").classList.add("live");
  $("snap").disabled = false;
  $("stop").classList.remove("hidden");
});

$("stop").addEventListener("click", stopCamera);

function stopCamera() {
  if (stream) stream.getTracks().forEach(t => t.stop());
  stream = null;
  $("preview").srcObject = null;
  $("camstate").textContent = "Camera off.";
  $("viewfinder").classList.remove("live");
  $("snap").disabled = true;
  $("stop").classList.add("hidden");
}

$("snap").addEventListener("click", async () => {
  $("err").classList.add("hidden");
  const handle = $("handle").value;
  if (!handle) return showErr("Enrol a device first.");
  const device = await vdGetDevice(handle);
  if (!device) return showErr("That device's key isn't in this browser. Re-enrol, or import its saved key from the Enrol page.");
  if (!stream) return showErr("Start the camera first.");

  $("snap").disabled = true;
  try {
    // 1. Grab the live frame straight off the video element into a canvas.
    const v = $("preview");
    const canvas = $("frame");
    canvas.width = v.videoWidth;
    canvas.height = v.videoHeight;
    canvas.getContext("2d").drawImage(v, 0, 0, canvas.width, canvas.height);

    // The shutter "flash" — a brief moment that says "got it," the way a
    // real camera app confirms a shot. Purely cosmetic; prefers-reduced-motion
    // already zeroes its animation duration (style.css's global rule).
    const flash = $("flash");
    flash.classList.remove("fire");
    void flash.offsetWidth; // restart the animation even on back-to-back captures
    flash.classList.add("fire");

    const rawBlob = await new Promise(r => canvas.toBlob(r, "image/png"));

    // 2. Fetch the freshness challenge AND reserve a manifest id now, before
    //    any embedding (decisions/0011). Everything that touches the file's
    //    bytes has to happen before hashing/signing, in this exact order:
    //    watermark, then the proof-code metadata, then the C2PA manifest
    //    last of all. That last part is the fix for a real bug: the proof
    //    code used to get added AFTER the C2PA manifest was signed, which
    //    silently broke C2PA's own internal hash-binding — any C2PA reader
    //    (including Veridact's own) then correctly reported the file as
    //    invalid, because from C2PA's point of view it genuinely was
    //    modified after signing. The manifest id has to exist up front so
    //    the proof code can be embedded before C2PA ever touches the file,
    //    not after. The challenge is still single-use and short-lived
    //    (decisions/0003); the embedding round-trips below take well under
    //    a second combined, nowhere near its TTL.
    const ch = await (await fetch("/capture/challenge")).json();
    const capturedAt = new Date().toISOString();

    // 3. Embed a soft-binding watermark into the RAW frame BEFORE hashing or
    //    signing anything (decisions/0009 §5 — order matters: watermarking
    //    AFTER signing would mean the saved file could never hash-match what
    //    was signed again, since embedding necessarily changes pixel bytes).
    //    This is a point in the flow where the frame touches the server
    //    before it's been attested — a generic "embed a secret" utility that
    //    proves nothing on its own; see decisions/0009 §5 for why that's safe.
    $("camstate").textContent = "Processing…";
    const wmForm = new FormData();
    wmForm.append("file", rawBlob, "frame.png");
    const wmRes = await fetch("/capture/watermark", { method: "POST", body: wmForm });
    if (!wmRes.ok) throw new Error("Could not prepare the capture for signing.");
    const watermarkSecret = wmRes.headers.get("X-Watermark-Secret");
    const watermarkedBlob = await wmRes.blob();

    // 4. Bake the proof code into the photo now (PNG metadata, decisions/0008)
    //    — BEFORE the C2PA manifest, not after (decisions/0011). This is the
    //    corrected order: C2PA's own hash covers the file as it exists at
    //    signing time, so anything meant to survive in the final file has to
    //    already be there before that step, never added on top of it.
    const withCode = await vdEmbedPngText(watermarkedBlob, "veridact-manifest-id", ch.manifest_id);

    // 5. Embed a real C2PA manifest — the industry-standard container a
    //    Leica or Sony would produce — signed with Veridact's own
    //    certificate, asserting exactly what's known at this point: the
    //    capture timestamp, the device, and the freshness-challenge response
    //    (decisions/0010). This is now the LAST thing that touches the
    //    file's bytes before hashing — nothing gets added on top of it.
    const c2paForm = new FormData();
    c2paForm.append("file", withCode, "frame.png");
    c2paForm.append("handle", handle);
    c2paForm.append("captured_at", capturedAt);
    c2paForm.append("challenge", ch.challenge);
    const c2paRes = await fetch("/capture/c2pa", { method: "POST", body: c2paForm });
    if (!c2paRes.ok) throw new Error("Could not prepare the capture for signing.");
    const blob = await c2paRes.blob();
    lastBlob = blob;
    $("camstate").textContent = `Live — ${v.videoWidth}x${v.videoHeight}`;

    // 6. NOW hash the final bytes (watermark + proof code + C2PA, in that
    //    order) — this is what gets signed, and it's also exactly the file
    //    that gets saved, so a freshly-saved capture always hash-matches
    //    what was signed, and nothing downstream can invalidate the C2PA
    //    manifest by modifying the file further.
    const bytes = await blob.arrayBuffer();
    const mediaHash = await sha256Hex(bytes);

    // 7. Sign hash + time + device + challenge with the device's stored key.
    //    No key text is read or parsed here — just used, directly.
    const message = manifestMessage(mediaHash, capturedAt, handle, ch.challenge);
    const sig = device.algorithm === "schnorr"
      ? await signManifest(device.privateScalar, message)
      : await signManifestEcdsaWithKey(device.cryptoKey, message);

    // 8. Send the manifest, the pre-reserved manifest id, and the watermark
    //    secret, so the server records this exact id (matching what's
    //    already embedded in the file) rather than minting a new one. The
    //    image itself already reached the server above — this call carries
    //    no file.
    const res = await fetch("/attest", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        handle, media_hash: mediaHash, captured_at: capturedAt,
        label: $("label").value.trim(), challenge: ch.challenge,
        t: sig.t, s: sig.s, watermark_secret: watermarkSecret,
        manifest_id: ch.manifest_id,
      }),
    });
    const d = await res.json();
    if (!res.ok) throw new Error(d.error);

    lastManifest = { ...d, challenge: ch.challenge, sig_t: sig.t, sig_s: sig.s };

    $("shot").src = URL.createObjectURL(lastBlob);
    $("shot").classList.remove("hidden");
    $("c_id").textContent = d.manifest_id;
    $("c_device").textContent = d.device;
    $("c_label").textContent = d.label;
    $("c_hash").textContent = d.media_hash;
    $("c_time").textContent = d.captured_at;
    const result = $("result");
    result.classList.remove("hidden", "pop");
    void result.offsetWidth; // restart the pop animation on repeat captures
    result.classList.add("pop");
    result.scrollIntoView({ behavior: "smooth" });
  } catch (e) {
    showErr(e.message);
  } finally {
    $("snap").disabled = !stream;
  }
});

$("download_img").addEventListener("click", () => {
  if (!lastBlob || !lastManifest) return;
  const a = document.createElement("a");
  a.href = URL.createObjectURL(lastBlob);
  a.download = lastManifest.manifest_id + ".png";
  a.click();
});

// The proof code (manifest ID) is still shown/copyable as a fallback — useful
// if this exact file gets recompressed and loses its embedded metadata — but
// it's no longer the thing you have to remember to save (decisions/0008).
$("copy_id").addEventListener("click", async () => {
  if (!lastManifest) return;
  await navigator.clipboard.writeText(lastManifest.manifest_id);
  const btn = $("copy_id");
  const original = btn.textContent;
  btn.textContent = "Copied!";
  setTimeout(() => { btn.textContent = original; }, 1500);
});

$("download").addEventListener("click", () => {
  if (!lastManifest) return;
  const blob = new Blob([JSON.stringify(lastManifest, null, 2)], { type: "application/json" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = lastManifest.manifest_id + ".json";
  a.click();
});

window.addEventListener("beforeunload", stopCamera);
